import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import base64
from io import BytesIO
import re
from collections import Counter

# ── Load Data ──
df = pd.read_csv('/app/benchmark/data.csv')

# ── Basic Stats ──
total_questions = len(df)
years = sorted(df['year'].unique())
num_years = len(years)
type_counts_overall = df['type'].value_counts()

yearly = df.groupby(['year', 'type']).size().unstack(fill_value=0)
yearly['Total'] = yearly.sum(axis=1)
yearly = yearly.reset_index()

# Ensure all types present
for t in ['MCQs', 'Short', 'Long']:
    if t not in yearly.columns:
        yearly[t] = 0

# Year-over-year change
yearly = yearly.sort_values('year')
yearly['YoY_Change'] = yearly['Total'].diff()
yearly['YoY_Pct_Change'] = yearly['Total'].pct_change() * 100

# Average per type
avg_per_type = {}
for t in ['MCQs', 'Short', 'Long']:
    avg_per_type[t] = yearly[t].mean()
avg_total = yearly['Total'].mean()

# ── Topic / Keyword Analysis ──
def extract_keywords(question_text):
    """Extract meaningful CS-related keywords from question text."""
    # Remove $-delimited MCQ options and sub-parts
    parts = question_text.split('$')
    # Take only the question stem (first part before $)
    stem = parts[0]

    # Common stop words
    stop_words = {
        'the', 'a', 'an', 'is', 'are', 'was', 'were', 'of', 'in', 'to', 'for',
        'and', 'or', 'by', 'with', 'from', 'this', 'that', 'it', 'its', 'any',
        'what', 'which', 'how', 'why', 'when', 'where', 'who', 'do', 'does',
        'can', 'write', 'define', 'explain', 'differentiate', 'between', 'give',
        'list', 'name', 'describe', 'identify', 'determine', 'rewrite', 'convert',
        'draw', 'debug', 'following', 'given', 'example', 'examples', 'following',
        'program', 'programs', 'statement', 'statements', 'function', 'functions',
        'also', 'called', 'used', 'use', 'using', 'into', 'each', 'two', 'three',
        'four', 'one', 'means', 'mean', 'let', 'will', 'may', 'not', 'no',
        'their', 'these', 'those', 'has', 'have', 'had', 'been', 'be', 'being',
        'than', 'more', 'such', 'some', 'other', 'all', 'both', 'above',
        'below', 'about', 'up', 'out', 'on', 'if', 'then', 'else', 'void',
        'int', 'main', 'printf', 'scanf', 'include', 'return', 'value', 'output',
        'input', 'number', 'numbers', 'print', 'full', 'form', 'purpose',
        'difference', 'advantages', 'types', 'type', 'various', 'different',
        'equivalent', 'format', 'syntax', 'structure', 'structures', 'correctly',
        'steps', 'create', 'role', 'components', 'characteristics', 'importance',
        'required', 'reason', 'case', 'cases', 'parts', 'part', 'within',
        'without', 'through', 'during', 'after', 'before', 'only', 'just',
        'following', 'below', 'given', 'respectively', 'etc', 'i.e', 'e.g',
        'represents', 'representation', 'sometimes', 'often', 'well', 'known',
        'refer', 'refers', 'computes', 'performs', 'considered', 'consider',
        'another', 'related', 'relationship', 'among', 'items', 'item',
        'data', 'c-language', 'c-language', 'c', 'language', 'program',
        'programming', 'database', 'ms-access', 'access',
    }

    # Extract words
    words = re.findall(r'[a-zA-Z][a-zA-Z0-9_#+-]*', stem.lower())

    keywords = []
    for w in words:
        if w not in stop_words and len(w) > 2:
            keywords.append(w)

    return keywords


all_keywords = []
keyword_by_year = {y: [] for y in years}
keyword_by_type = {t: [] for t in ['MCQs', 'Short', 'Long']}

for _, row in df.iterrows():
    kws = extract_keywords(str(row['question']))
    all_keywords.extend(kws)
    keyword_by_year[row['year']].extend(kws)
    keyword_by_type[row['type']].extend(kws)

top_keywords = Counter(all_keywords).most_common(30)

# Topic categories for broader analysis
topic_categories = {
    'Loop & Iteration': ['loop', 'while', 'for', 'do-while', 'nested', 'iteration', 'continue', 'break', 'repeat'],
    'Conditional Logic': ['if', 'else', 'switch', 'case', 'conditional', 'decision', 'nested-if', 'ladder'],
    'Functions & Recursion': ['function', 'recursive', 'recursion', 'prototype', 'call', 'parameter', 'argument', 'return', 'library', 'user-defined'],
    'Data Types & Variables': ['data-type', 'variable', 'constant', 'int', 'float', 'char', 'double', 'string', 'global', 'local', 'scope', 'storage'],
    'Operators & Expressions': ['operator', 'arithmetic', 'relational', 'logical', 'assignment', 'increment', 'decrement', 'bitwise', 'ternary', 'precedence', 'modulus', 'unary', 'binary', 'comparison'],
    'I/O & Formatting': ['printf', 'scanf', 'input', 'output', 'format-specifier', 'escape', 'precision', 'field-width', 'getch', 'gets', 'puts', 'putchar', 'getc', 'formatted', 'unformatted'],
    'Arrays & Strings': ['array', 'string', 'character', 'strlen', 'substring'],
    'Pointers & Structures': ['pointer', 'structure', 'union', 'typedef'],
    'File Handling': ['file', 'fopen', 'fclose', 'fscanf', 'fprintf', 'data-file', 'mode', 'opening'],
    'Preprocessor & Headers': ['preprocessor', 'directive', 'header', 'include', 'define', 'stdio', 'conio', 'math'],
    'DBMS Fundamentals': ['dbms', 'rdbms', 'database', 'record', 'field', 'attribute', 'tuple', 'entity', 'table', 'schema', 'normalization', 'redundancy', 'integrity', 'dictionary', 'dba'],
    'Keys & Relationships': ['primary-key', 'foreign-key', 'key', 'candidate', 'composite', 'alternate', 'super', 'relationship', 'one-to-many', 'one-to-one', 'many-to-many', 'referential', 'relational'],
    'SQL & DDL/DML': ['sql', 'ddl', 'dml', 'dcl', 'tcl', 'query', 'select', 'query'],
    'Database Models': ['hierarchical', 'network', 'relational', 'object-oriented', 'flat', 'model', 'er-diagram', 'normal-form'],
    'MS Access': ['access', 'form', 'report', 'query', 'macro', 'module', 'object', 'auto-number', 'currency', 'ole'],
    'Error & Debugging': ['error', 'syntax', 'logical', 'runtime', 'debug', 'compiler', 'interpreter', 'valid', 'invalid', 'identifier', 'reserved'],
}

# Count topic occurrences per year
topic_by_year = {}
for cat_name, cat_keywords in topic_categories.items():
    topic_by_year[cat_name] = {}
    for y in years:
        year_counter = Counter(keyword_by_year[y])
        count = sum(year_counter.get(kw, 0) for kw in cat_keywords)
        topic_by_year[cat_name][y] = count

# Overall topic frequency
topic_overall = {cat: sum(topic_by_year[cat].values()) for cat in topic_categories}
topic_overall_sorted = sorted(topic_overall.items(), key=lambda x: x[1], reverse=True)


# ── Chart Generation Helpers ──
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    b64 = base64.b64encode(buf.getvalue()).decode()
    plt.close(fig)
    return b64


# Color palette
COLORS = {
    'MCQs': '#3B82F6',      # Blue
    'Short': '#10B981',      # Green
    'Long': '#F59E0B',       # Amber
    'Total': '#6366F1',      # Indigo
    'bg': '#F8FAFC',
    'grid': '#E2E8F0',
    'text': '#1E293B',
    'accent': '#6366F1',
}

plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.facecolor': '#F8FAFC',
    'figure.facecolor': '#FFFFFF',
    'axes.edgecolor': '#CBD5E1',
    'axes.labelcolor': '#334155',
    'xtick.color': '#475569',
    'ytick.color': '#475569',
    'grid.color': '#E2E8F0',
    'grid.alpha': 0.7,
})


# ── Chart 1: Total Questions by Year (Line + Area) ──
fig1, ax1 = plt.subplots(figsize=(10, 5))
ax1.fill_between(yearly['year'], yearly['Total'], alpha=0.15, color=COLORS['Total'])
ax1.plot(yearly['year'], yearly['Total'], marker='o', linewidth=2.5, color=COLORS['Total'], markersize=8, zorder=5)
for _, row in yearly.iterrows():
    ax1.annotate(str(int(row['Total'])), (row['year'], row['Total']),
                 textcoords="offset points", xytext=(0, 12), ha='center', fontsize=10, fontweight='bold', color=COLORS['Total'])
ax1.set_xlabel('Examination Year')
ax1.set_ylabel('Total Questions')
ax1.set_title('Total Questions per Examination Year (2015–2025)', fontsize=14, fontweight='bold', pad=15)
ax1.set_xticks(yearly['year'])
ax1.grid(True, axis='y', linestyle='--')
ax1.set_ylim(0, yearly['Total'].max() * 1.2)
chart1_b64 = fig_to_base64(fig1)


# ── Chart 2: Stacked Bar — Question Type Composition ──
fig2, ax2 = plt.subplots(figsize=(10, 5.5))
bar_width = 0.6
x_pos = range(len(yearly))
bars_mcq = ax2.bar(x_pos, yearly['MCQs'], bar_width, label='MCQs', color=COLORS['MCQs'], edgecolor='white', linewidth=0.5)
bars_short = ax2.bar(x_pos, yearly['Short'], bar_width, bottom=yearly['MCQs'], label='Short', color=COLORS['Short'], edgecolor='white', linewidth=0.5)
bars_long = ax2.bar(x_pos, yearly['Long'], bar_width, bottom=yearly['MCQs'] + yearly['Short'], label='Long', color=COLORS['Long'], edgecolor='white', linewidth=0.5)
ax2.set_xticks(x_pos)
ax2.set_xticklabels(yearly['year'])
ax2.set_xlabel('Examination Year')
ax2.set_ylabel('Number of Questions')
ax2.set_title('Question Type Composition by Year', fontsize=14, fontweight='bold', pad=15)
ax2.legend(loc='upper right', framealpha=0.9)
ax2.grid(True, axis='y', linestyle='--', alpha=0.5)
chart2_b64 = fig_to_base64(fig2)


# ── Chart 3: Line chart — Question Type Trends ──
fig3, ax3 = plt.subplots(figsize=(10, 5))
ax3.plot(yearly['year'], yearly['MCQs'], marker='s', linewidth=2, color=COLORS['MCQs'], label='MCQs', markersize=7)
ax3.plot(yearly['year'], yearly['Short'], marker='^', linewidth=2, color=COLORS['Short'], label='Short', markersize=7)
ax3.plot(yearly['year'], yearly['Long'], marker='D', linewidth=2, color=COLORS['Long'], label='Long', markersize=7)
ax3.set_xlabel('Examination Year')
ax3.set_ylabel('Number of Questions')
ax3.set_title('Question Type Trends Across Years', fontsize=14, fontweight='bold', pad=15)
ax3.set_xticks(yearly['year'])
ax3.legend(loc='upper right', framealpha=0.9)
ax3.grid(True, linestyle='--', alpha=0.7)
chart3_b64 = fig_to_base64(fig3)


# ── Chart 4: Pie chart — Overall Question Type Distribution ──
fig4, ax4 = plt.subplots(figsize=(6, 6))
type_vals = [type_counts_overall.get(t, 0) for t in ['MCQs', 'Short', 'Long']]
type_labels = ['MCQs', 'Short Questions', 'Long Questions']
type_colors = [COLORS['MCQs'], COLORS['Short'], COLORS['Long']]
wedges, texts, autotexts = ax4.pie(type_vals, labels=type_labels, colors=type_colors, autopct='%1.1f%%',
                                     startangle=90, textprops={'fontsize': 11}, pctdistance=0.75,
                                     wedgeprops={'edgecolor': 'white', 'linewidth': 2})
for t in autotexts:
    t.set_fontweight('bold')
    t.set_color('white')
ax4.set_title('Overall Question Type Distribution (2015–2025)', fontsize=13, fontweight='bold', pad=15)
chart4_b64 = fig_to_base64(fig4)


# ── Chart 5: Top 15 Keywords Bar Chart ──
fig5, ax5 = plt.subplots(figsize=(10, 6))
top15 = top_keywords[:15]
kw_labels = [k[0] for k in top15]
kw_counts = [k[1] for k in top15]
bars = ax5.barh(range(len(top15)), kw_counts, color=COLORS['accent'], edgecolor='white', height=0.65)
ax5.set_yticks(range(len(top15)))
ax5.set_yticklabels(kw_labels, fontsize=10)
ax5.invert_yaxis()
ax5.set_xlabel('Frequency')
ax5.set_title('Top 15 Recurring Keywords in Examination Questions', fontsize=14, fontweight='bold', pad=15)
ax5.grid(True, axis='x', linestyle='--', alpha=0.5)
for bar, val in zip(bars, kw_counts):
    ax5.text(bar.get_width() + 0.5, bar.get_y() + bar.get_height()/2, str(val),
             va='center', fontsize=10, fontweight='bold', color='#334155')
chart5_b64 = fig_to_base64(fig5)


# ── Chart 6: Topic Category Heatmap-style Stacked Bar ──
fig6, ax6 = plt.subplots(figsize=(12, 6))
top_topics = [t for t, _ in topic_overall_sorted[:10]]
bottom = [0] * len(years)
topic_colors_list = plt.cm.Set3([i / len(top_topics) for i in range(len(top_topics))])
for idx, topic in enumerate(top_topics):
    vals = [topic_by_year[topic][y] for y in years]
    ax6.bar(years, vals, bottom=bottom, label=topic, color=topic_colors_list[idx], edgecolor='white', linewidth=0.3)
    bottom = [b + v for b, v in zip(bottom, vals)]
ax6.set_xlabel('Examination Year')
ax6.set_ylabel('Keyword Frequency')
ax6.set_title('Topic Category Distribution Across Years', fontsize=14, fontweight='bold', pad=15)
ax6.set_xticks(years)
ax6.legend(loc='upper right', fontsize=8, ncol=2, framealpha=0.9)
ax6.grid(True, axis='y', linestyle='--', alpha=0.5)
chart6_b64 = fig_to_base64(fig6)


# ── Chart 7: Year-over-Year Change ──
fig7, ax7 = plt.subplots(figsize=(10, 5))
colors_yoy = ['#10B981' if v >= 0 else '#EF4444' for v in yearly['YoY_Change'].fillna(0)]
ax7.bar(yearly['year'], yearly['YoY_Change'].fillna(0), color=colors_yoy, edgecolor='white', width=0.6)
ax7.axhline(0, color='#94A3B8', linewidth=0.8)
ax7.set_xlabel('Examination Year')
ax7.set_ylabel('Change in Question Count')
ax7.set_title('Year-over-Year Change in Total Questions', fontsize=14, fontweight='bold', pad=15)
ax7.set_xticks(yearly['year'])
ax7.grid(True, axis='y', linestyle='--', alpha=0.5)
chart7_b64 = fig_to_base64(fig7)


# ── Chart 8: Type Ratio (%) by Year ──
fig8, ax8 = plt.subplots(figsize=(10, 5))
for t, color in [('MCQs', COLORS['MCQs']), ('Short', COLORS['Short']), ('Long', COLORS['Long'])]:
    pct = (yearly[t] / yearly['Total'] * 100).round(1)
    ax8.plot(yearly['year'], pct, marker='o', linewidth=2, color=color, label=t, markersize=7)
ax8.set_xlabel('Examination Year')
ax8.set_ylabel('Percentage of Total Questions (%)')
ax8.set_title('Question Type Ratio (%) Across Years', fontsize=14, fontweight='bold', pad=15)
ax8.set_xticks(yearly['year'])
ax8.legend(framealpha=0.9)
ax8.grid(True, linestyle='--', alpha=0.7)
ax8.set_ylim(0, 60)
chart8_b64 = fig_to_base64(fig8)


# ── Build HTML Report ──
# Build yearly data table rows
yearly_table_rows = ""
for _, row in yearly.iterrows():
    y = int(row['year'])
    mcq = int(row['MCQs'])
    short = int(row['Short'])
    long_q = int(row['Long'])
    total = int(row['Total'])
    yoy = row['YoY_Change']
    yoy_pct = row['YoY_Pct_Change']
    mcq_pct = round(mcq / total * 100, 1) if total else 0
    short_pct = round(short / total * 100, 1) if total else 0
    long_pct = round(long_q / total * 100, 1) if total else 0

    yoy_str = "—"
    if pd.notna(yoy):
        sign = "+" if yoy > 0 else ""
        yoy_str = f"{sign}{int(yoy)} ({sign}{yoy_pct:.1f}%)"

    highlight = ""
    if pd.notna(yoy) and abs(yoy_pct) >= 20:
        highlight = ' style="background-color:#FEF3C7;"'

    yearly_table_rows += f"""<tr{highlight}>
        <td>{y}</td><td>{mcq} ({mcq_pct}%)</td><td>{short} ({short_pct}%)</td>
        <td>{long_q} ({long_pct}%)</td><td><strong>{total}</strong></td><td>{yoy_str}</td>
    </tr>\n"""

# Build top keywords table
kw_table_rows = ""
for i, (kw, count) in enumerate(top_keywords, 1):
    kw_table_rows += f"<tr><td>{i}</td><td>{kw}</td><td>{count}</td></tr>\n"

# Build topic category table
topic_table_rows = ""
for cat, count in topic_overall_sorted:
    if count > 0:
        pct = round(count / len(all_keywords) * 100, 1)
        topic_table_rows += f"<tr><td>{cat}</td><td>{count}</td><td>{pct}%</td></tr>\n"

# KPI cards
mcq_total = type_counts_overall.get('MCQs', 0)
short_total = type_counts_overall.get('Short', 0)
long_total = type_counts_overall.get('Long', 0)
max_year_row = yearly.loc[yearly['Total'].idxmax()]
min_year_row = yearly.loc[yearly['Total'].idxmin()]

# Missing year note
missing_years = []
for y in range(2015, 2026):
    if y not in years:
        missing_years.append(str(y))
missing_note = ", ".join(missing_years) if missing_years else "None"

# Build type-by-year detail
type_detail_rows = ""
for t in ['MCQs', 'Short', 'Long']:
    type_detail_rows += f"""<tr>
        <td>{t}</td>
        <td>{int(type_counts_overall.get(t, 0))}</td>
        <td>{round(type_counts_overall.get(t, 0) / total_questions * 100, 1)}%</td>
        <td>{round(avg_per_type[t], 1)}</td>
        <td>{int(yearly.loc[yearly[t].idxmax(), 'year'])} ({int(yearly[t].max())})</td>
        <td>{int(yearly.loc[yearly[t].idxmin(), 'year'])} ({int(yearly[t].min())})</td>
    </tr>\n"""


html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>BIEK Computer Science 12th Class Past Paper Analysis (2015–2025)</title>
<style>
    :root {{
