        'draw', 'debug', 'following', 'given', 'example', 'examples', 'following',
        'program', 'programs', 'statement', 'statements', 'function', 'functions',
        'also', 'called', 'used', 'use', 'using', 'into', 'each', 'two', 'three',
        'four', 'one', 'means', 'mean', 'let', 'will', 'may', 'not', 'no',
        'their', 'these', 'those', 'has', 'have', 'had', 'been', 'be', 'being',
        'than', 'more', 'such', 'some', 'other', 'all', 'both', 'above',
        'below', 'about', 'up', 'out', 'on', 'if', 'then', 'else', 'void',
        'int', 'main', 'printf', 'scanf', 'include', 'return', 'value', 'output',
        'input', 'number', 'numbers', 'print', 'full', 'form', 'purpose',
        'difference', 'advantages', 'types', 'type', 'various', 'different',
        'equivalent', 'format', 'syntax', 'structure', 'structures', 'correctly',
        'steps', 'create', 'role', 'components', 'characteristics', 'importance',
        'required', 'reason', 'case', 'cases', 'parts', 'part', 'within',
        'without', 'through', 'during', 'after', 'before', 'only', 'just',
        'following', 'below', 'given', 'respectively', 'etc', 'i.e', 'e.g',
        'represents', 'representation', 'sometimes', 'often', 'well', 'known',
        'refer', 'refers', 'computes', 'performs', 'considered', 'consider',
        'another', 'related', 'relationship', 'among', 'items', 'item',
        'data', 'c-language', 'c-language', 'c', 'language', 'program',
        'programming', 'database', 'ms-access', 'access',
    }

    # Extract words
    words = re.findall(r'[a-zA-Z][a-zA-Z0-9_#+-]*', stem.lower())

    keywords = []
    for w in words:
        if w not in stop_words and len(w) > 2:
            keywords.append(w)

    return keywords


all_keywords = []
keyword_by_year = {y: [] for y in years}
keyword_by_type = {t: [] for t in ['MCQs', 'Short', 'Long']}

for _, row in df.iterrows():
    kws = extract_keywords(str(row['question']))
    all_keywords.extend(kws)
    keyword_by_year[row['year']].extend(kws)
    keyword_by_type[row['type']].extend(kws)

top_keywords = Counter(all_keywords).most_common(30)

# Topic categories for broader analysis
topic_categories = {
    'Loop & Iteration': ['loop', 'while', 'for', 'do-while', 'nested', 'iteration', 'continue', 'break', 'repeat'],
    'Conditional Logic': ['if', 'else', 'switch', 'case', 'conditional', 'decision', 'nested-if', 'ladder'],
    'Functions & Recursion': ['function', 'recursive', 'recursion', 'prototype', 'call', 'parameter', 'argument', 'return', 'library', 'user-defined'],
    'Data Types & Variables': ['data-type', 'variable', 'constant', 'int', 'float', 'char', 'double', 'string', 'global', 'local', 'scope', 'storage'],
