ax1.set_title('Total Questions per Examination Year (2015–2025)', fontsize=14, fontweight='bold', pad=15)
ax1.set_xticks(yearly['year'])
ax1.grid(True, axis='y', linestyle='--')
ax1.set_ylim(0, yearly['Total'].max() * 1.2)
chart1_b64 = fig_to_base64(fig1)


# ── Chart 2: Stacked Bar — Question Type Composition ──
fig2, ax2 = plt.subplots(figsize=(10, 5.5))
bar_width = 0.6
