ax2.legend(loc='upper right', framealpha=0.9)
ax2.grid(True, axis='y', linestyle='--', alpha=0.5)
chart2_b64 = fig_to_base64(fig2)


# ── Chart 3: Line chart — Question Type Trends ──
fig3, ax3 = plt.subplots(figsize=(10, 5))
