import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import base64
from io import BytesIO
import re
from collections import Counter

# ── Load Data ──
df = pd.read_csv('/app/benchmark/data.csv')

# ── Basic Stats ──
total_questions = len(df)
years = sorted(df['year'].unique())
num_years = len(years)
type_counts_overall = df['type'].value_counts()

yearly = df.groupby(['year', 'type']).size().unstack(fill_value=0)
yearly['Total'] = yearly.sum(axis=1)
yearly = yearly.reset_index()

# Ensure all types present
for t in ['MCQs', 'Short', 'Long']:
    if t not in yearly.columns:
        yearly[t] = 0

# Year-over-year change
yearly = yearly.sort_values('year')
yearly['YoY_Change'] = yearly['Total'].diff()
yearly['YoY_Pct_Change'] = yearly['Total'].pct_change() * 100

# Average per type
avg_per_type = {}
for t in ['MCQs', 'Short', 'Long']:
    avg_per_type[t] = yearly[t].mean()
avg_total = yearly['Total'].mean()

# ── Topic / Keyword Analysis ──
def extract_keywords(question_text):
    """Extract meaningful CS-related keywords from question text."""
    # Remove $-delimited MCQ options and sub-parts
    parts = question_text.split('$')
    # Take only the question stem (first part before $)
    stem = parts[0]

    # Common stop words
    stop_words = {
        'the', 'a', 'an', 'is', 'are', 'was', 'were', 'of', 'in', 'to', 'for',
        'and', 'or', 'by', 'with', 'from', 'this', 'that', 'it', 'its', 'any',
        'what', 'which', 'how', 'why', 'when', 'where', 'who', 'do', 'does',
        'can', 'write', 'define', 'explain', 'differentiate', 'between', 'give',
        'list', 'name', 'describe', 'identify', 'determine', 'rewrite', 'convert',
        'draw', 'debug', 'following', 'given', 'example', 'examples', 'following',
        'program', 'programs', 'statement', 'statements', 'function', 'functions',
        'also', 'called', 'used', 'use', 'using', 'into', 'each', 'two', 'three',
        'four', 'one', 'means', 'mean', 'let', 'will', 'may', 'not', 'no',
        'their', 'these', 'those', 'has', 'have', 'had', 'been', 'be', 'being',
        'than', 'more', 'such', 'some', 'other', 'all', 'both', 'above',
        'below', 'about', 'up', 'out', 'on', 'if', 'then', 'else', 'void',
        'int', 'main', 'printf', 'scanf', 'include', 'return', 'value', 'output',
        'input', 'number', 'numbers', 'print', 'full', 'form', 'purpose',
        'difference', 'advantages', 'types', 'type', 'various', 'different',
        'equivalent', 'format', 'syntax', 'structure', 'structures', 'correctly',
        'steps', 'create', 'role', 'components', 'characteristics', 'importance',
        'required', 'reason', 'case', 'cases', 'parts', 'part', 'within',
        'without', 'through', 'during', 'after', 'before', 'only', 'just',
        'following', 'below', 'given', 'respectively', 'etc', 'i.e', 'e.g',
        'represents', 'representation', 'sometimes', 'often', 'well', 'known',
        'refer', 'refers', 'computes', 'performs', 'considered', 'consider',
        'another', 'related', 'relationship', 'among', 'items', 'item',
        'data', 'c-language', 'c-language', 'c', 'language', 'program',
        'programming', 'database', 'ms-access', 'access',
    }

    # Extract words
    words = re.findall(r'[a-zA-Z][a-zA-Z0-9_#+-]*', stem.lower())

    keywords = []
    for w in words:
        if w not in stop_words and len(w) > 2:
            keywords.append(w)

    return keywords


all_keywords = []
keyword_by_year = {y: [] for y in years}
keyword_by_type = {t: [] for t in ['MCQs', 'Short', 'Long']}

for _, row in df.iterrows():
    kws = extract_keywords(str(row['question']))
    all_keywords.extend(kws)
    keyword_by_year[row['year']].extend(kws)
    keyword_by_type[row['type']].extend(kws)

top_keywords = Counter(all_keywords).most_common(30)

# Topic categories for broader analysis
topic_categories = {
    'Loop & Iteration': ['loop', 'while', 'for', 'do-while', 'nested', 'iteration', 'continue', 'break', 'repeat'],
    'Conditional Logic': ['if', 'else', 'switch', 'case', 'conditional', 'decision', 'nested-if', 'ladder'],
    'Functions & Recursion': ['function', 'recursive', 'recursion', 'prototype', 'call', 'parameter', 'argument', 'return', 'library', 'user-defined'],
    'Data Types & Variables': ['data-type', 'variable', 'constant', 'int', 'float', 'char', 'double', 'string', 'global', 'local', 'scope', 'storage'],
    'Operators & Expressions': ['operator', 'arithmetic', 'relational', 'logical', 'assignment', 'increment', 'decrement', 'bitwise', 'ternary', 'precedence', 'modulus', 'unary', 'binary', 'comparison'],
    'I/O & Formatting': ['printf', 'scanf', 'input', 'output', 'format-specifier', 'escape', 'precision', 'field-width', 'getch', 'gets', 'puts', 'putchar', 'getc', 'formatted', 'unformatted'],
    'Arrays & Strings': ['array', 'string', 'character', 'strlen', 'substring'],
    'Pointers & Structures': ['pointer', 'structure', 'union', 'typedef'],
    'File Handling': ['file', 'fopen', 'fclose', 'fscanf', 'fprintf', 'data-file', 'mode', 'opening'],
    'Preprocessor & Headers': ['preprocessor', 'directive', 'header', 'include', 'define', 'stdio', 'conio', 'math'],
    'DBMS Fundamentals': ['dbms', 'rdbms', 'database', 'record', 'field', 'attribute', 'tuple', 'entity', 'table', 'schema', 'normalization', 'redundancy', 'integrity', 'dictionary', 'dba'],
    'Keys & Relationships': ['primary-key', 'foreign-key', 'key', 'candidate', 'composite', 'alternate', 'super', 'relationship', 'one-to-many', 'one-to-one', 'many-to-many', 'referential', 'relational'],
    'SQL & DDL/DML': ['sql', 'ddl', 'dml', 'dcl', 'tcl', 'query', 'select', 'query'],
    'Database Models': ['hierarchical', 'network', 'relational', 'object-oriented', 'flat', 'model', 'er-diagram', 'normal-form'],
    'MS Access': ['access', 'form', 'report', 'query', 'macro', 'module', 'object', 'auto-number', 'currency', 'ole'],
    'Error & Debugging': ['error', 'syntax', 'logical', 'runtime', 'debug', 'compiler', 'interpreter', 'valid', 'invalid', 'identifier', 'reserved'],
}

# Count topic occurrences per year
topic_by_year = {}
for cat_name, cat_keywords in topic_categories.items():
    topic_by_year[cat_name] = {}
    for y in years:
        year_counter = Counter(keyword_by_year[y])
        count = sum(year_counter.get(kw, 0) for kw in cat_keywords)
        topic_by_year[cat_name][y] = count

# Overall topic frequency
topic_overall = {cat: sum(topic_by_year[cat].values()) for cat in topic_categories}
topic_overall_sorted = sorted(topic_overall.items(), key=lambda x: x[1], reverse=True)


# ── Chart Generation Helpers ──
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    b64 = base64.b64encode(buf.getvalue()).decode()
    plt.close(fig)
    return b64


# Color palette
COLORS = {
    'MCQs': '#3B82F6',      # Blue
    'Short': '#10B981',      # Green
    'Long': '#F59E0B',       # Amber
    'Total': '#6366F1',      # Indigo
    'bg': '#F8FAFC',
    'grid': '#E2E8F0',
    'text': '#1E293B',
    'accent': '#6366F1',
}

plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.facecolor': '#F8FAFC',
    'figure.facecolor': '#FFFFFF',
    'axes.edgecolor': '#CBD5E1',
    'axes.labelcolor': '#334155',
